const {chromium}=require('playwright');const assert=require('node:assert/strict');
(async()=>{
 const base=process.env.ALPHA_BASE_URL||'https://tuuvo.app.br';
 const browser=await chromium.launch({headless:true,executablePath:process.env.CHROME_PATH||'/usr/bin/google-chrome'});
 try{
  const page=await browser.newPage({viewport:{width:1280,height:900}}),errors=[];page.on('pageerror',e=>errors.push(e.message));
  await page.goto(base+'/experience',{waitUntil:'networkidle'});
  const legacy=await page.evaluate(async()=>{let s=await(await fetch('/api/demo/start')).json();while(!s.finished)s=await(await fetch('/api/demo/step',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({history:s.history,phase:s.phase.id,choice:s.phase.choices[0].id})})).json();const legacy={history:s.history,attempts:[s.history]};localStorage.setItem('tuuvo-jornada-alpha1',JSON.stringify(legacy));return JSON.stringify(legacy)});
  assert.equal(await page.locator('.experience-card').count(),2);await page.screenshot({path:'/tmp/alpha-browser/escolha-experiencias.png',fullPage:true});
  await page.locator('#select-medical').click();await page.getByRole('button',{name:'Começar a experiência',exact:true}).click();
  await page.locator('#context').waitFor({state:'visible'});assert.match(await page.locator('#phaseCount').textContent(),/DE 7/);assert.match(await page.locator('#sourcePanel').textContent(),/CC BY 4.0/);
  await page.getByRole('button',{name:'Reproduzir vídeo com narração',exact:true}).click();await page.waitForFunction(()=>{const v=document.querySelector('video');return v.readyState>=2&&!v.paused&&v.currentTime>1});
  const audible=await page.locator('video').evaluate(async video=>{const ctx=new AudioContext();await ctx.resume();const source=ctx.createMediaElementSource(video),analyser=ctx.createAnalyser();source.connect(analyser);analyser.connect(ctx.destination);window.__medicalAudio=ctx;const samples=new Float32Array(analyser.fftSize);for(let n=0;n<50;n++){analyser.getFloatTimeDomainData(samples);if(samples.some(x=>Math.abs(x)>.002))return true;await new Promise(r=>setTimeout(r,50))}return false});assert.equal(audible,true);
  const choose=async(index,next)=>{await page.locator('#choices button').nth(index).click();if(next)await page.waitForFunction(n=>document.querySelector('#phaseCount').textContent.includes('FASE '+n+' DE'),next);else await page.locator('#results').waitFor({state:'visible'})};
  await choose(2,2);await choose(0,3);await page.getByRole('button',{name:'Pausar jornada',exact:true}).click();await page.locator('#catalogBack').click();
  assert.equal(await page.evaluate(()=>localStorage.getItem('tuuvo-jornada-alpha1')),legacy,'Medical changes must not overwrite legacy corporate storage');
  await page.locator('#select-corporate').click();await page.getByRole('button',{name:'Ver minha síntese',exact:true}).click();assert.equal(await page.locator('#firstScore').textContent(),'100.0');assert.equal(await page.locator('.phase-row').count(),6);assert.equal(await page.locator('#sourcePanel').isVisible(),false);
  await page.locator('#catalogBack').click();await page.locator('#select-medical').click();await page.getByRole('button',{name:'Retomar meu percurso',exact:true}).click();await page.waitForFunction(()=>document.querySelector('#phaseCount').textContent.includes('FASE 3 DE 7'));
  await choose(2,4);await choose(0,5);assert.match(await page.locator('#context').textContent(),/oportunidade de retomar/);await choose(0,6);assert.match(await page.locator('#context').textContent(),/descobriu que Ana trabalha em turnos/);await choose(0,7);await choose(0);
  assert.equal(await page.locator('#firstScore').textContent(),'71.4');assert.equal(await page.locator('.phase-row').count(),7);assert.match(await page.locator('#resultCount').textContent(),/7 DE 7/);assert.match(await page.locator('#evidence').textContent(),/Fonte: Capítulo/);await page.waitForFunction(()=>document.querySelector('#comparison').getAttribute('aria-busy')==='false');
  assert.match(await page.locator('#scope option').first().textContent(),/turmas fictícias/);
  const download=page.waitForEvent('download');await page.locator('#download').click();const file=await download;assert.equal(file.suggestedFilename(),'tuuvo-consulta-minha-sintese.txt');const stream=await file.createReadStream();const chunks=[];for await(const chunk of stream)chunks.push(chunk);const report=Buffer.concat(chunks).toString();assert.match(report,/Uma consulta, uma pessoa/);assert.match(report,/CC BY 4.0/);assert.match(report,/pendente de revisão docente/);
  await page.screenshot({path:'/tmp/alpha-browser/diagnostico-medical.png',fullPage:true});await page.locator('#retry').click();for(let i=0;i<7;i++)await choose(2,i<6?i+2:0);assert.equal(await page.locator('#firstScore').textContent(),'71.4');assert.equal(await page.locator('#currentScore').textContent(),'0.0');assert.match(await page.locator('#attemptCount').textContent(),/2 percursos/);
  await page.locator('#catalogBack').click();await page.locator('#select-corporate').click();await page.getByRole('button',{name:'Ver minha síntese',exact:true}).click();assert.equal(await page.locator('#currentScore').textContent(),'100.0');await page.locator('#clear').click();await page.locator('#catalogBack').click();await page.reload({waitUntil:'networkidle'});await page.locator('#select-medical').click();await page.getByRole('button',{name:'Ver minha síntese',exact:true}).click();assert.equal(await page.locator('#firstScore').textContent(),'71.4');assert.match(await page.locator('#attemptCount').textContent(),/2 percursos/);
  await page.setViewportSize({width:390,height:844});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);await page.screenshot({path:'/tmp/alpha-browser/medical-mobile.png',fullPage:true});await page.locator('#catalogBack').click();assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);await page.screenshot({path:'/tmp/alpha-browser/escolha-mobile.png',fullPage:true});assert.deepEqual(errors,[]);
  console.log('PASS: two experiences, narrated medical video, seven phases, missed disclosure and repair, sources, report, independent progress and attempts, legacy history preserved, mobile and no JS errors');
 }finally{await browser.close()}
})().catch(e=>{console.error('::error title=Medical journey validation::'+e.message.replace(/\n/g,'%0A').replace(/\r/g,'%0D'));process.exit(1)});
